import { createDatasetLoader } from '@/lib/dataset-loader';

/**
 * OSM way tags sampled along the CLDT and run-length encoded. Generated by
 * `scripts/enrich-trail-osm.ts` and served at /trail-osm-tags.json. Consumed
 * at runtime by the surface- and SAC-difficulty trail-style color modes.
 */

export type SacScale =
	| 'hiking'
	| 'mountain_hiking'
	| 'demanding_mountain_hiking'
	| 'alpine_hiking'
	| 'demanding_alpine_hiking'
	| 'difficult_alpine_hiking';

export interface TrailOsmTagRun {
	fromKm: number;
	toKm: number;
	surface: string | null;
	highway: string | null;
	sac_scale: SacScale | null;
	mtb_scale: string | null;
}

export interface TrailOsmTagsFile {
	lastUpdated: string;
	totalKm: number;
	sampleStepM?: number;
	runs: TrailOsmTagRun[];
}

/**
 * Overlap length in km between two km ranges [aFrom, aTo] and [bFrom, bTo].
 * Returns 0 when the ranges are disjoint or either range has zero (or negative)
 * length. Shared by the surface breakdown / dominant-surface and SAC-max range
 * scans so the clamp-and-subtract math lives in one place.
 */
export function rangeOverlapKm(aFrom: number, aTo: number, bFrom: number, bTo: number): number {
	const start = Math.max(aFrom, bFrom);
	const end = Math.min(aTo, bTo);
	return end > start ? end - start : 0;
}

/**
 * Coarse surface buckets mapped from the long tail of OSM surface=* values.
 * Drives the surface-color-mode palette so the legend only has 5 entries
 * rather than every conceivable surface tag.
 */
export type SurfaceBucket = 'paved' | 'unpaved' | 'gravel' | 'ground' | 'rock' | 'unknown';

/** Canonical display order for surface-mix rows (elevation chart + section tooltips). */
export const SURFACE_BUCKETS: readonly SurfaceBucket[] = ['paved', 'unpaved', 'gravel', 'ground', 'rock', 'unknown'];

/**
 * Maps an OSM surface=* value to a coarse bucket. Returns 'unknown' for
 * untagged or unrecognized surfaces so the renderer can color them
 * distinctly rather than dropping them. The mapping leans conservative for
 * hikers: anything that's clearly trail (ground / dirt / earth / grass /
 * mud) collapses to 'ground'; track-like surfaces (gravel / compacted /
 * fine_gravel / pebblestone) collapse to 'gravel'; rock / scree / sand
 * stay as 'rock' so dangerous-footing surfaces are flagged distinctly.
 */
export function bucketSurface(value: string | null | undefined): SurfaceBucket {
	if (!value) return 'unknown';
	const v = value.toLowerCase().trim();
	switch (v) {
		case 'paved':
		case 'asphalt':
		case 'concrete':
		case 'paving_stones':
		case 'sett':
		case 'cobblestone':
		case 'metal':
		case 'wood':
			return 'paved';
		case 'unpaved':
		case 'compacted':
			return 'unpaved';
		case 'gravel':
		case 'fine_gravel':
		case 'pebblestone':
			return 'gravel';
		case 'ground':
		case 'dirt':
		case 'earth':
		case 'grass':
		case 'mud':
		case 'sand':
			return 'ground';
		case 'rock':
		case 'scree':
		case 'stone':
			return 'rock';
		default:
			return 'unknown';
	}
}

/**
 * SAC scale buckets with a synthetic 'untagged' value for runs where the
 * OSM way has no sac_scale tag (the bulk of non-alpine terrain). Keeping
 * 'untagged' as a first-class bucket lets the renderer choose to color it
 * neutrally rather than hiding it.
 */
export type SacBucket = SacScale | 'untagged';

export function bucketSac(value: SacScale | null | undefined): SacBucket {
	return value ?? 'untagged';
}

/** SAC scale severity order, easiest (T1) to hardest (T6); array index = rank. */
export const SAC_SCALE_ORDER: readonly SacScale[] = [
	'hiking',
	'mountain_hiking',
	'demanding_mountain_hiking',
	'alpine_hiking',
	'demanding_alpine_hiking',
	'difficult_alpine_hiking',
];

/**
 * Highest-severity sac_scale tagged across runs overlapping [fromKm, toKm]
 * (SOBO km, order-independent). Returns null when no overlapping run carries a
 * sac_scale tag - callers use that to omit the difficulty line entirely.
 */
export function sacMaxForKmRange(runs: TrailOsmTagRun[], fromKm: number, toKm: number): SacScale | null {
	const lo = Math.min(fromKm, toKm);
	const hi = Math.max(fromKm, toKm);
	let maxRank = -1;
	let result: SacScale | null = null;
	for (const run of runs) {
		if (!run.sac_scale) continue;
		if (rangeOverlapKm(run.fromKm, run.toKm, lo, hi) <= 0) continue;
		const rank = SAC_SCALE_ORDER.indexOf(run.sac_scale);
		if (rank > maxRank) {
			maxRank = rank;
			result = run.sac_scale;
		}
	}
	return result;
}

/** Defensive bound to refuse remote payloads that exceed plausible run counts.
 *  A 2,200 km trail at fine OSM tagging produces at most ~10 k runs in practice. */
const MAX_RUNS = 50_000;

/** Defensive cap for any OSM tag string; bucket functions only consume known
 *  short values (e.g. "paved", "T3") and fall back to "unknown" / "untagged"
 *  for anything else, so longer strings are pure memory waste. */
const MAX_TAG_LEN = 64;

function isTagField(v: unknown): boolean {
	// Treat omitted (undefined) fields as null so a remote payload that drops
	// optional tags is accepted rather than rejecting the entire run.
	return v === null || (typeof v === 'string' && v.length <= MAX_TAG_LEN);
}

function isValidRun(r: unknown): r is TrailOsmTagRun {
	if (!r || typeof r !== 'object') return false;
	const o = r as Record<string, unknown>;
	return (
		Number.isFinite(o.fromKm) &&
		Number.isFinite(o.toKm) &&
		(o.fromKm as number) <= (o.toKm as number) &&
		isTagField(o.surface) &&
		isTagField(o.highway) &&
		isTagField(o.sac_scale) &&
		isTagField(o.mtb_scale)
	);
}

function normalize(raw: Partial<TrailOsmTagsFile>): TrailOsmTagsFile | null {
	if (!raw || typeof raw !== 'object') return null;
	if (!Array.isArray(raw.runs)) return null;
	if (raw.runs.length > MAX_RUNS) return null;
	if (!raw.runs.every(isValidRun)) return null;
	return {
		// Coerce rather than pass through: a remote payload can put any JSON value here.
		lastUpdated: typeof raw.lastUpdated === 'string' ? raw.lastUpdated : '',
		totalKm: typeof raw.totalKm === 'number' ? raw.totalKm : 0,
		sampleStepM: raw.sampleStepM,
		runs: raw.runs,
	};
}

const trailOsmTagsLoader = createDatasetLoader({
	remoteUrl: process.env.NEXT_PUBLIC_TRAIL_OSM_TAGS_URL,
	localPath: '/trail-osm-tags.json',
	normalize: (raw) => normalize(raw as Partial<TrailOsmTagsFile>),
});

/**
 * Loads the OSM tag dataset: the remote override when NEXT_PUBLIC_TRAIL_OSM_TAGS_URL
 * is set (https only), then the bundled /trail-osm-tags.json. Cached for the page;
 * after resetTrailOsmTagsCache() the next load revalidates and keeps the same
 * object when the dataset did not change.
 */
export const loadTrailOsmTags = trailOsmTagsLoader.load;

/** Marks the dataset stale: the next loadTrailOsmTags call revalidates. */
export const resetTrailOsmTagsCache = trailOsmTagsLoader.reset;

/**
 * Binary-search the run array for the run that contains the given km. Returns
 * null if km is outside every run (typically end-of-trail past the last run's
 * toKm, or before the first run starts).
 */
export function findRunAtKm(runs: TrailOsmTagRun[], km: number): TrailOsmTagRun | null {
	if (runs.length === 0) return null;
	let lo = 0;
	let hi = runs.length - 1;
	while (lo <= hi) {
		const mid = (lo + hi) >> 1;
		const r = runs[mid];
		if (km < r.fromKm) hi = mid - 1;
		else if (km > r.toKm) lo = mid + 1;
		else return r;
	}
	return null;
}
